def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_actions = [h[1] for h in history]
    opp_defects = 0
    for a in opp_actions:
        if a == 'D':
            opp_defects += 1
    rate = opp_defects / n

    run_d = 0
    for a in reversed(opp_actions):
        if a == 'D':
            run_d += 1
        else:
            break

    last_op = opp_actions[-1]

    if last_op == 'C':
        return 'C'

    if run_d == 1:
        if rate < 0.2:
            if rng.random() < 0.8:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
    elif run_d == 2:
        if rate < 0.3:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
    else:
        if rate < 0.3:
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
